$savedInclude = [Environment]::GetEnvironmentVariable('C1_INCLUDE', 'Process')
$savedStandard = [Environment]::GetEnvironmentVariable('C1_STANDARD', 'Process')
try {
    [Environment]::SetEnvironmentVariable('C1_INCLUDE', [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../include')), 'Process')
    $runtime = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../lib/runtime.c'))
    $nl = [string][char]10
    $prefix = ('#include <stdlib.h>', '#include <limits.h>', '#include <string.h>', '#include <errno.h>', 'int ascending(const void *a,const void *b){int x=*(const int *)a,y=*(const int *)b;return (x>y)-(x<y);}', 'int descending(const void *a,const void *b){return -ascending(a,b);}', '') -join $nl
    $suffix = $nl + '#include "' + $runtime + '"' + $nl
    foreach ($mode in 'c89', 'c99') {
        [Environment]::SetEnvironmentVariable('C1_STANDARD', $mode, 'Process')
        $cases = @{
            'sort-exhaustive-duplicates' = 'int main(void){int a[8],hist[3],n,total=1,code,x,i,j,k;for(n=0;n<=8;n++){for(code=0;code<total;code++){hist[0]=0;hist[1]=0;hist[2]=0;x=code;for(i=0;i<n;i++){a[i]=x%3-1;hist[x%3]++;x/=3;}qsort(a,n,sizeof(int),ascending);k=0;for(j=0;j<3;j++)for(i=0;i<hist[j];i++)if(a[k++]!=j-1)return 1;}total*=3;}return 0;}'
            'sort-extremes' = 'int main(void){int a[]={INT_MAX,0,INT_MIN,-1,1,INT_MAX,INT_MIN};int expected[]={INT_MIN,INT_MIN,-1,0,1,INT_MAX,INT_MAX};int i;qsort(a,7,sizeof(int),ascending);for(i=0;i<7;i++)if(a[i]!=expected[i])return 1;qsort(a,7,sizeof(int),descending);for(i=0;i<7;i++)if(a[i]!=expected[6-i])return 2;return 0;}'
            'sort-lengths' = 'int main(void){int a[258],n,i;for(n=0;n<=256;n++){a[0]=73;a[n+1]=97;for(i=0;i<n;i++)a[i+1]=n-i;qsort(a+1,n,sizeof(int),ascending);for(i=0;i<n;i++)if(a[i+1]!=i+1)return 1;if(a[0]!=73||a[n+1]!=97)return 2;qsort(a+1,n,sizeof(int),ascending);for(i=0;i<n;i++)if(a[i+1]!=i+1)return 3;}return 0;}'
            'sort-empty-single' = 'int calls;int cmp(const void *a,const void *b){calls++;return ascending(a,b);}int main(void){int a=7;qsort(&a,0,sizeof(a),cmp);if(calls||a!=7)return 1;qsort(&a,1,sizeof(a),cmp);return calls||a!=7;}'
            'sort-byte-elements' = 'int cmp(const void *a,const void *b){return (int)*(const unsigned char *)a-(int)*(const unsigned char *)b;}int main(void){unsigned char a[256];int i;for(i=0;i<256;i++)a[i]=(unsigned char)(255-i);qsort(a,256,1,cmp);for(i=0;i<256;i++)if(a[i]!=i)return 1;return 0;}'
            'sort-wide-elements' = 'int cmp(const void *a,const void *b){unsigned long long x=*(const unsigned long long *)a,y=*(const unsigned long long *)b;return(x>y)-(x<y);}int main(void){unsigned long long a[]={ULLONG_MAX,0,4294967296ULL,9223372036854775808ULL,1},expected[]={0,1,4294967296ULL,9223372036854775808ULL,ULLONG_MAX};int i;qsort(a,5,sizeof(a[0]),cmp);for(i=0;i<5;i++)if(a[i]!=expected[i])return 1;return 0;}'
            'sort-odd-width' = 'int cmp(const void *a,const void *b){return (int)*(const unsigned char *)a-(int)*(const unsigned char *)b;}int main(void){unsigned char a[32][3];int i;for(i=0;i<32;i++){a[i][0]=(unsigned char)(31-i);a[i][1]=(unsigned char)(a[i][0]+100);a[i][2]=(unsigned char)(a[i][0]^85);}qsort(a,32,3,cmp);for(i=0;i<32;i++)if(a[i][0]!=i||a[i][1]!=i+100||a[i][2]!=(i^85))return 1;return 0;}'
            'sort-large-records' = 'struct S{int key,id;unsigned char payload[257];};int cmp(const void *a,const void *b){const struct S *x=a,*y=b;return(x->key>y->key)-(x->key<y->key);}int main(void){struct S a[33],before[33];int i,j;unsigned long long seen=0;memset(a,165,sizeof(a));for(i=0;i<33;i++){a[i].key=(32-i)%7;a[i].id=i;for(j=0;j<257;j++)a[i].payload[j]=(unsigned char)(i*17+j);}memcpy(before,a,sizeof(a));qsort(a,33,sizeof(a[0]),cmp);for(i=0;i<33;i++){if(i&&a[i-1].key>a[i].key)return 1;if(a[i].id<0||a[i].id>=33)return 2;if(seen&(1ULL<<a[i].id))return 3;seen|=1ULL<<a[i].id;if(memcmp(&a[i],&before[a[i].id],sizeof(a[0])))return 4;}return seen!=8589934591ULL;}'
            'sort-pointer-elements' = 'int cmp(const void *a,const void *b){const char *const *x=a,*const *y=b;return strcmp(*x,*y);}int main(void){const char *a[]={"z","ab","","a","ab","Z"};const char *e[]={"","Z","a","ab","ab","z"};int i;qsort(a,6,sizeof(a[0]),cmp);for(i=0;i<6;i++)if(strcmp(a[i],e[i]))return 1;return 0;}'
            'sort-callback-locations' = 'int *begin;int count,bad,calls;int cmp(const void *a,const void *b){size_t x=(size_t)a,y=(size_t)b,lo=(size_t)begin,hi=lo+count*sizeof(int);calls++;if(x<lo||y<lo||x>=hi||y>=hi||(x-lo)%sizeof(int)||(y-lo)%sizeof(int)){bad=1;return 0;}return ascending(a,b);}int main(void){int a[64],i;begin=a;count=64;for(i=0;i<64;i++)a[i]=63-i;qsort(a,64,sizeof(int),cmp);if(bad||!calls)return 1;for(i=0;i<64;i++)if(a[i]!=i)return 2;return 0;}'
            'sort-reentrant' = 'int bad;int cmp(const void *a,const void *b){int inner[]={5,3,1,4,2},i;qsort(inner,5,sizeof(int),ascending);for(i=0;i<5;i++)if(inner[i]!=i+1)bad=1;return ascending(a,b);}int main(void){int a[]={8,6,7,5,3,0,9},e[]={0,3,5,6,7,8,9},i;qsort(a,7,sizeof(int),cmp);if(bad)return 1;for(i=0;i<7;i++)if(a[i]!=e[i])return 2;return 0;}'
            'search-empty-single' = 'int calls;int cmp(const void *a,const void *b){calls++;return ascending(a,b);}int main(void){int a=7,key=7;if(bsearch(&key,&a,0,sizeof(a),cmp)!=NULL||calls)return 1;if(bsearch(&key,&a,1,sizeof(a),cmp)!=&a||calls!=1)return 2;key=6;if(bsearch(&key,&a,1,sizeof(a),cmp)!=NULL)return 3;key=8;return bsearch(&key,&a,1,sizeof(a),cmp)!=NULL;}'
            'search-all-positions' = 'int main(void){int a[128],n,i,key,*found;for(n=0;n<=128;n++){for(i=0;i<n;i++)a[i]=2*i;for(key=-1;key<=2*n;key++){found=bsearch(&key,a,n,sizeof(int),ascending);if(key>=0&&key<2*n&&!(key%2)){if(found!=a+key/2)return 1;}else if(found!=NULL)return 2;}}return 0;}'
            'search-duplicates' = 'int main(void){int a[]={1,1,1,2,2,2,3,3,3},key,*p;for(key=1;key<=3;key++){p=bsearch(&key,a,9,sizeof(int),ascending);if(!p||*p!=key||p<a||p>=a+9)return 1;}key=0;if(bsearch(&key,a,9,sizeof(int),ascending)!=NULL)return 2;key=4;return bsearch(&key,a,9,sizeof(int),ascending)!=NULL;}'
            'search-descending' = 'int main(void){int a[]={9,7,5,3,1},key,*p;for(key=0;key<=10;key++){p=bsearch(&key,a,5,sizeof(int),descending);if(key%2){if(!p||*p!=key)return 1;}else if(p)return 2;}return 0;}'
            'search-key-order-records' = 'struct S{int id;char name[8];};const void *expected_key;int bad;int cmp(const void *key,const void *element){const struct S *s=element;if(key!=expected_key){bad=1;return 0;}return strcmp(key,s->name);}int main(void){const struct S a[]={{3,"alpha"},{7,"beta"},{9,"gamma"}};const char *keys[]={"alpha","beta","gamma","delta"};const struct S *p;int i;for(i=0;i<4;i++){expected_key=keys[i];p=bsearch(keys[i],a,3,sizeof(a[0]),cmp);if(bad)return 1;if(i<3){if(p!=a+i)return 2;}else if(p)return 3;}return 0;}'
            'search-no-write' = 'int main(void){const int a[]={-7,-3,0,3,7};int key=3;int *p=bsearch(&key,a,5,sizeof(int),ascending);return p!=a+3||key!=3||a[0]!=-7||a[1]!=-3||a[2]!=0||a[3]!=3||a[4]!=7;}'
            'search-partition-only' = 'int main(void){int a[]={3,1,2,4,4,4,9,7,8};int key=4,*p=bsearch(&key,a,9,sizeof(int),ascending);return !p||*p!=4||p<a+3||p>=a+6;}'
            'search-comparator-sign' = 'int cmp(const void *a,const void *b){int r=ascending(a,b);return r<0?INT_MIN:r>0?INT_MAX:0;}int main(void){int a[]={5,4,3,2,1},i;qsort(a,5,sizeof(int),cmp);for(i=1;i<=5;i++)if(bsearch(&i,a,5,sizeof(int),cmp)!=a+i-1)return 1;return 0;}'
            'function-pointers' = 'int main(void){void (*sort)(void *,size_t,size_t,int (*)(const void *,const void *))=qsort;void *(*find)(const void *,const void *,size_t,size_t,int (*)(const void *,const void *))=bsearch;int a[]={3,1,2},key=2,n=3;sort(a,n++,sizeof(int),ascending);if(n!=4)return 1;return find(&key,a,3,sizeof(int),ascending)!=a+1;}'
            'heap-integration' = 'int main(void){int *a=malloc(4096*sizeof(int)),i,key,*p;if(!a)return 1;for(i=0;i<4096;i++)a[i]=(i*2053+17)%4096;qsort(a,4096,sizeof(int),ascending);for(i=0;i<4096;i++)if(a[i]!=i)return 2;for(key=0;key<4096;key+=31){p=bsearch(&key,a,4096,sizeof(int),ascending);if(p!=a+key)return 3;}free(a);return 0;}'
            'errno-preserved' = 'int main(void){int a[]={3,2,1},key=2;errno=ERANGE;qsort(a,3,sizeof(int),ascending);if(errno!=ERANGE)return 1;if(bsearch(&key,a,3,sizeof(int),ascending)!=a+1)return 2;return errno!=ERANGE;}'
        }
        foreach ($name in ($cases.Keys | Sort-Object)) {
            Check "search-$mode-$name" ($prefix + $cases[$name] + $suffix) 
        }
    }
}
finally {
    [Environment]::SetEnvironmentVariable('C1_INCLUDE', $savedInclude, 'Process')
    [Environment]::SetEnvironmentVariable('C1_STANDARD', $savedStandard, 'Process')
}
